settings.custom_liquid:
{%- assign sc_image = product.metafields.custom.size_chart_image -%}
{%- if sc_image != blank -%}
  <style>
    .ks-sizeguide-btn {
      display:inline-flex; align-items:center; gap:8px;
      padding:10px 14px; border:1px solid #111; border-radius:999px;
      background:#fff; color:#111; font-weight:600; cursor:pointer;
      transition:transform .12s ease, background .12s ease, color .12s ease;
    }
    .ks-sizeguide-btn:hover { transform:translateY(-1px); }

    .ks-sc-backdrop {
      position:fixed; inset:0; background:rgba(0,0,0,.5);
      display:none; align-items:center; justify-content:center; z-index:9999;
    }
    .ks-sc-backdrop.ks-open { display:flex; }

    .ks-sc-modal {
      width:min(900px, 92vw); max-height:90vh; overflow:auto;
      background:#fff; border-radius:16px; box-shadow:0 20px 60px rgba(0,0,0,.25);
      position:relative; padding:20px;
    }
    .ks-sc-close {
      position:absolute; top:10px; right:10px;
      width:32px; height:32px; border:none; background:#fff;
      border-radius:50%; font-size:20px; cursor:pointer;
    }
    .ks-sc-content img {
      width:100%; height:auto; border-radius:10px;
    }
  </style>

  <button type="button" class="ks-sizeguide-btn" data-sc-open>
    <svg width="18" height="18" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5h16v2H4V5zm0 6h16v2H4v-2zm0 6h10v2H4v-2z" fill="currentColor"/></svg>
    Size Guide
  </button>

  <div class="ks-sc-backdrop" data-sc-backdrop>
    <div class="ks-sc-modal">
      <button type="button" class="ks-sc-close" data-sc-close>&times;</button>
      <div class="ks-sc-content">
        <img src="{{ sc_image | image_url }}" alt="{{ product.title }} Size Chart">
      </div>
    </div>
  </div>

  <script>
    (function(){
      var openBtn = document.querySelector('[data-sc-open]');
      var backdrop = document.querySelector('[data-sc-backdrop]');
      var closeBtn = document.querySelector('[data-sc-close]');
      if(!openBtn || !backdrop) return;
      openBtn.addEventListener('click', ()=>{backdrop.classList.add('ks-open');document.body.style.overflow='hidden';});
      closeBtn.addEventListener('click', ()=>{backdrop.classList.remove('ks-open');document.body.style.overflow='';});
      backdrop.addEventListener('click', e=>{if(e.target===backdrop){backdrop.classList.remove('ks-open');document.body.style.overflow='';}});
    })();
  </script>
{%- endif -%}

{%- assign details_mf = product.metafields.kasya.details -%}
{%- assign size_fit_mf = product.metafields.kasya.size_fit -%}
{%- assign care_mf = product.metafields.kasya.care -%}
{%- assign style_tips_mf = product.metafields.kasya.style_tips -%}
{%- assign ship_returns_mf = product.metafields.kasya.shipping_returns -%}

{%- if details_mf != blank or size_fit_mf != blank or care_mf != blank or style_tips_mf != blank or ship_returns_mf != blank -%}

<style>
/* ========= OA PREMIUM ACCORDION ========= */
.kasya-acc{
  margin-top:34px;
  border-top:1px solid rgba(0,0,0,.14);
}

/* Item */
.kasya-acc__item{
  border-bottom:1px solid rgba(0,0,0,.14);
  padding:8px 0;
  position: relative;
  transition: background .35s ease, box-shadow .35s ease;
}

/* Open state highlight */
.kasya-acc__item[open]{
  background: rgba(0,0,0,.02);
  box-shadow: inset 0 0 0 9999px rgba(0,0,0,.012);
}

/* Left accent bar when open */
.kasya-acc__item[open]::before{
  content:"";
  position:absolute;
  left:0;
  top:10px;
  bottom:10px;
  width:3px;
  background: rgba(0,0,0,.55);
  border-radius: 3px;
  opacity:.75;
}

/* Title row */
.kasya-acc__item summary{
  list-style:none;
  cursor:pointer;
  padding:26px 0;              /* ⬅️ mas airy */
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:16px;
  font-weight:800;
  font-size:1.42rem;           /* ⬅️ HEADER MAS MALAKI */
  letter-spacing:.2px;
  transition: transform .25s ease, opacity .25s ease;
  user-select:none;
  -webkit-user-select:none;
}

.kasya-acc__item summary:hover{
  transform: translateX(8px);
  opacity:.92;
}

.kasya-acc__item summary::-webkit-details-marker{ display:none; }

/* Icon */
.kasya-acc__icon{
  width:28px;
  height:28px;
  flex:0 0 28px;
  position:relative;
  transform-origin:center;
  transition: transform .35s cubic-bezier(.2,.9,.2,1);
}

.kasya-acc__icon:before,
.kasya-acc__icon:after{
  content:"";
  position:absolute;
  left:0;
  right:0;
  top:50%;
  height:2.4px;                /* ⬅️ thicker */
  background:currentColor;
  transform:translateY(-50%);
  opacity:.9;
}

.kasya-acc__icon:after{
  transform:translateY(-50%) rotate(90deg);
  transition: transform .35s cubic-bezier(.2,.9,.2,1);
}

/* Open icon: pop + rotate + tiny bounce */
details[open] .kasya-acc__icon{
  transform: rotate(180deg) scale(1.18);
}

details[open] .kasya-acc__icon:after{
  transform:translateY(-50%) rotate(0deg);
}

/* Content: BIG + animated */
.kasya-acc__content{
  overflow:hidden;
  max-height:0;
  opacity:0;
  transform: translateY(-18px) scale(.985);
  transition: max-height .55s cubic-bezier(.2,.9,.2,1),
              opacity .35s ease,
              transform .45s ease;
  padding: 0;
  font-size:1.22rem;           /* ⬅️ DESCRIPTION MAS MALAKI */
  line-height:1.95;            /* ⬅️ airy */
  color: rgba(0,0,0,.88);
}

/* Open */
details[open] .kasya-acc__content{
  max-height: 1600px;
  opacity:1;
  transform: translateY(0) scale(1);
  padding: 0 0 28px 0;
}

/* Text spacing */
.kasya-acc__content p{ margin:0 0 16px 0; }
.kasya-acc__content p:last-child{ margin-bottom:0; }
.kasya-acc__content ul,
.kasya-acc__content ol{ margin:14px 0 0 24px; }
.kasya-acc__content li{ margin:10px 0; }

/* Optional: subtle "glow" on open (not too neon) */
.kasya-acc__item[open]{
  box-shadow: 0 10px 30px rgba(0,0,0,.06);
  border-radius: 10px;
  padding-left: 12px;
  padding-right: 12px;
}

/* Reduce motion accessibility */
@media (prefers-reduced-motion: reduce){
  .kasya-acc__item,
  .kasya-acc__item summary,
  .kasya-acc__icon,
  .kasya-acc__icon:after,
  .kasya-acc__content{
    transition:none !important;
  }
}
</style>

<div class="kasya-acc" aria-label="Product information">

  {%- if details_mf != blank -%}
    <details class="kasya-acc__item">
      <summary>
        <span>Product Details</span>
        <span class="kasya-acc__icon" aria-hidden="true"></span>
      </summary>
      <div class="kasya-acc__content">
        {{ details_mf | metafield_tag }}
      </div>
    </details>
  {%- endif -%}

  {%- if size_fit_mf != blank -%}
    <details class="kasya-acc__item">
      <summary>
        <span>Size &amp; Fit</span>
        <span class="kasya-acc__icon" aria-hidden="true"></span>
      </summary>
      <div class="kasya-acc__content">
        {{ size_fit_mf | metafield_tag }}
      </div>
    </details>
  {%- endif -%}

  {%- if care_mf != blank -%}
    <details class="kasya-acc__item">
      <summary>
        <span>Care Instructions</span>
        <span class="kasya-acc__icon" aria-hidden="true"></span>
      </summary>
      <div class="kasya-acc__content">
        {{ care_mf | metafield_tag }}
      </div>
    </details>
  {%- endif -%}

  {%- if style_tips_mf != blank -%}
    <details class="kasya-acc__item">
      <summary>
        <span>Style Tips</span>
        <span class="kasya-acc__icon" aria-hidden="true"></span>
      </summary>
      <div class="kasya-acc__content">
        {{ style_tips_mf | metafield_tag }}
      </div>
    </details>
  {%- endif -%}

  {%- if ship_returns_mf != blank -%}
    <details class="kasya-acc__item">
      <summary>
        <span>Shipping &amp; Returns</span>
        <span class="kasya-acc__icon" aria-hidden="true"></span>
      </summary>
      <div class="kasya-acc__content">
        {{ ship_returns_mf | metafield_tag }}
      </div>
    </details>
  {%- endif -%}

</div>

<script>
/* ONE OPEN AT A TIME */
(function(){
  var items = document.querySelectorAll('.kasya-acc__item');
  items.forEach(function(item){
    item.addEventListener('toggle', function(){
      if (item.open){
        items.forEach(function(other){
          if (other !== item) other.removeAttribute('open');
        });
      }
    });
  });
})();
</script>

{%- endif -%}
